local bigNumber = 10^40 -- math.huge (inf value) also works, but it bugs the character. Modify it if u want inf.
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local RFrequest_buy = ReplicatedStorage.Libraries.Net["RF/request_buy"] -- RemoteFunction 

RFrequest_buy:InvokeServer(
    "Upgrade",
    {
        Price = -bigNumber,
        Currency = "Wins",
        Amount = bigNumber
    }
)

RFrequest_buy:InvokeServer(
    "Rebirth",
    {
        Price = 1,
        Currency = "Size",
        Amount = bigNumber
    }
)
